BEGIN TRANSACTION READ ONLY;
WITH target_relations AS (
 SELECT c.oid,c.relname,c.relkind,c.relowner,c.relrowsecurity,c.relforcerowsecurity,c.relacl,n.nspname
 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
 WHERE n.nspname='public' AND c.relkind IN('r','p') AND c.relname IN('admin_audit_logs','admin_impersonation_tokens','admin_onboarding_invites','admin_role_permissions','admin_step_up_authorizations','ai_usage','alerts','bookings','bot_conversation_bindings','bot_translation_overrides','bot_translation_platform_overrides','business_bank_accounts','business_broadcasts','business_members','business_payment_credentials','business_payouts','businesses','campaign_donations','coexistence_signup_nonces','contract_signers','contract_templates','contracts','conversation_usage','countries','customer_profiles','customer_subscriptions','engage_segments','event_cancellation_recipients','event_cancelled_payment_followups','event_invites','event_mutation_operations','event_ticket_emissions','event_ticket_issuance_state','event_ticket_types','event_tickets','events','flow_dropoffs','form_responses','forms','fraud_events','growth_pricing','invoices','llm_classifications','loyalty_transactions','membership_tiers','messaging_allowances','oauth_connect_states','parties','party_reminder_attempts','party_reminder_runs','party_seating_commits','party_seating_group_tables','party_seating_groups','party_tables','payments','payout_accounts','payout_adjustments','pending_transfers','platform_fee_invoices','products','profiles','refunds','reseller_invoices','reseller_payouts','resellers','reservations','saved_payment_methods','seating_resources','signed_waivers','subscription_payments','subscriptions','waiver_templates','whatsapp_channels','whatsapp_inbound_receipts','whatsapp_signup_sessions')),
 target_functions AS (
 SELECT p.*,n.nspname FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname IN('public','private','accounting_private','subscription_private') AND
 (p.oid IN(SELECT tgfoid FROM pg_trigger WHERE tgrelid IN(SELECT oid FROM target_relations) AND NOT tgisinternal)
 OR p.proname IN('_save_commercial_config_impl','_save_market_messaging_config_impl','_save_messaging_config_impl','_toggle_messaging_suspension_impl','activate_paid_subscription','activate_trial_if_eligible','apply_payment_loyalty_once','approve_paid_order','assign_guest_to_table','authorize_event_ticket_emission','authorize_message_send','book_slot_atomic','book_table_atomic','bulk_assign_guests_to_table','calculate_volume_discount','cancel_pending_booking_for_navigation','cancel_pending_reservation_for_navigation','cancel_stale_order_atomic','category_text','check_business_role','check_conversation_limit','check_session_exists','claim_event_cancellation_notification','claim_payment_finalization','claim_payment_finalization_with_verified_fee','claim_paystack_billing_cycle','claim_recurring_billing_cycle','cleanup_expired_step_ups','complete_owner_subscription_downgrade','complete_party_rsvp_489','confirm_nonorder_transfer_atomic','confirm_order_transfer_atomic','contract_signers_enforce_signed_lock','contracts_enforce_signer_rows','contracts_enforce_signing_mode_immutable','converge_event_ticket_booking','create_order_atomic','create_ticket_booking_checked','disconnect_payout_account','dispatch_paystack_attempt','enforce_invite_capacity','event_finality_guard','finalize_event_cancellation_notification','finalize_event_ticket_emission','finalize_free_ticket_booking','finalize_paystack_recurring_charge','finalize_promo_reservation','force_settle_executed_transfer','generate_event_slug','generate_party_slug','get_business_revenue','get_order_revenue','get_outstanding_invoices','get_shared_conversation','guard_messaging_suspended','guard_party_answers_489','guard_party_capacity_reduction','guard_party_questions_489','guard_party_reminders_490','guard_payment_gateway_fee_claim','guard_seating_resource_delete','guard_server_managed_columns','guard_table_capacity_reduction','guard_table_identity','has_admin_role','has_platform_role','is_admin','is_admin_or_finance','is_admin_or_support','is_support','issue_api_key','list_cancelled_flutterwave_claims','mark_event_cancellation_notification_attempted','mark_trial_ineligible','mutate_event','party_questions_489','party_seating_486','party_seating_allowed_guard_486','party_seating_invite_486','party_seating_lock_486','party_seating_snapshot_486','persist_verified_paystack_card_authorization','prevent_ticket_capacity_decrease','prevent_tier_tampering','purchase_tickets_atomic','record_event_cancelled_payment_followup','redeem_loyalty_reward_once','reject_paid_order','reschedule_booking_atomic','revoke_api_key','save_commercial_config','save_market_messaging_config','save_messaging_config','save_provider_plan_refs','search_businesses_fuzzy','select_shared_conversation','serialize_capacity_writes','submit_transfer_proof','svc_save_commercial_config','svc_save_market_messaging_config','svc_toggle_messaging_suspension','swap_payout_account','terminate_cancelled_event_confirmation','toggle_messaging_suspension','update_customer_subscriptions_updated_at','update_updated_at','validate_invite_table_membership','validate_party_answers_489','validate_party_questions_489','validate_party_table_ownership'))),
 objects AS (
 SELECT 'schema:'||n.nspname AS identity,jsonb_build_object('owner',pg_get_userbyid(n.nspowner),'acl',(SELECT coalesce(jsonb_agg(jsonb_build_object('grantee',CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,'grantor',pg_get_userbyid(a.grantor),'privilege',a.privilege_type,'grantable',a.is_grantable) ORDER BY CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END COLLATE "C",a.privilege_type COLLATE "C"),'[]') FROM aclexplode(coalesce(n.nspacl,acldefault('n',n.nspowner))) a)) AS value FROM pg_namespace n WHERE n.nspname IN('private','subscription_private')
 UNION ALL SELECT 'table:'||nspname||'.'||relname AS identity,jsonb_build_object('kind',relkind,'owner',pg_get_userbyid(relowner),'rls',relrowsecurity,'force_rls',relforcerowsecurity,'acl',(SELECT coalesce(jsonb_agg(jsonb_build_object('grantee',CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,'grantor',pg_get_userbyid(a.grantor),'privilege',a.privilege_type,'grantable',a.is_grantable) ORDER BY CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END COLLATE "C",a.privilege_type COLLATE "C",a.grantor),'[]') FROM aclexplode(coalesce(relacl,acldefault('r',relowner))) a)) AS value FROM target_relations
 UNION ALL SELECT 'column:'||r.nspname||'.'||r.relname||'.'||a.attname,jsonb_build_object('type',format_type(a.atttypid,a.atttypmod),'notnull',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid),'generated',a.attgenerated,'identity',a.attidentity,'acl',(SELECT coalesce(jsonb_agg(jsonb_build_object('grantee',CASE WHEN x.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(x.grantee) END,'grantor',pg_get_userbyid(x.grantor),'privilege',x.privilege_type,'grantable',x.is_grantable) ORDER BY CASE WHEN x.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(x.grantee) END COLLATE "C",x.privilege_type COLLATE "C",x.grantor),'[]') FROM aclexplode(a.attacl) x)) FROM target_relations r JOIN pg_attribute a ON a.attrelid=r.oid LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attnum>0 AND NOT a.attisdropped
 UNION ALL SELECT 'constraint:'||r.nspname||'.'||r.relname||'.'||c.conname,jsonb_build_object('definition',pg_get_constraintdef(c.oid,true),'validated',c.convalidated,'deferrable',c.condeferrable,'deferred',c.condeferred) FROM target_relations r JOIN pg_constraint c ON c.conrelid=r.oid
 UNION ALL SELECT 'index:'||r.nspname||'.'||r.relname||'.'||ic.relname,jsonb_build_object('definition',pg_get_indexdef(i.indexrelid),'valid',i.indisvalid,'ready',i.indisready,'unique',i.indisunique,'primary',i.indisprimary,'predicate',pg_get_expr(i.indpred,i.indrelid)) FROM target_relations r JOIN pg_index i ON i.indrelid=r.oid JOIN pg_class ic ON ic.oid=i.indexrelid
 UNION ALL SELECT 'trigger:'||r.nspname||'.'||r.relname||'.'||t.tgname,jsonb_build_object('definition',pg_get_triggerdef(t.oid,true),'enabled',t.tgenabled) FROM target_relations r JOIN pg_trigger t ON t.tgrelid=r.oid WHERE NOT t.tgisinternal
 UNION ALL SELECT 'policy:'||r.nspname||'.'||r.relname||'.'||p.policyname,jsonb_build_object('command',p.cmd,'roles',p.roles,'using',p.qual,'with_check',p.with_check,'permissive',p.permissive) FROM target_relations r JOIN pg_policies p ON p.schemaname=r.nspname AND p.tablename=r.relname
 UNION ALL SELECT 'function:'||p.nspname||'.'||p.proname||'('||pg_get_function_identity_arguments(p.oid)||')',jsonb_build_object('owner',pg_get_userbyid(p.proowner),'body_sha256',encode(sha256(convert_to(p.prosrc,'UTF8')),'hex'),'arguments',pg_get_function_arguments(p.oid),'returns',pg_get_function_result(p.oid),'kind',p.prokind,'language',l.lanname,'config',p.proconfig,'definer',p.prosecdef,'strict',p.proisstrict,'volatility',p.provolatile,'parallel',p.proparallel,'leakproof',p.proleakproof,'acl',(SELECT coalesce(jsonb_agg(jsonb_build_object('grantee',CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,'grantor',pg_get_userbyid(a.grantor),'privilege',a.privilege_type,'grantable',a.is_grantable) ORDER BY CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END COLLATE "C",a.privilege_type COLLATE "C",a.grantor),'[]') FROM aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a)) FROM target_functions p JOIN pg_language l ON l.oid=p.prolang
)
SELECT jsonb_build_object('category_enum_labels',(SELECT jsonb_agg(en.enumlabel ORDER BY en.enumlabel COLLATE "C") FROM pg_enum en JOIN pg_type ty ON ty.oid=en.enumtypid JOIN pg_namespace ns ON ns.oid=ty.typnamespace WHERE ns.nspname='public' AND ty.typname='business_category'),'observed_at',clock_timestamp(),'read_only',current_setting('transaction_read_only'),'server_version',current_setting('server_version_num'),'objects',(SELECT jsonb_agg(jsonb_build_object('identity',identity,'value',value) ORDER BY identity COLLATE "C") FROM objects),'extensions',(SELECT jsonb_agg(jsonb_build_object('name',extname,'version',extversion)) FROM pg_extension WHERE extname IN('pg_trgm','pgcrypto','uuid-ossp'))) AS complete_catalog;
COMMIT;
